import{_ as s,o as i,c as e,ag as n}from"./chunks/framework.BZohXCq9.js";const k=JSON.parse('{"title":"DMA-BUF Heaps 与 CMA：RK3588 连续内存模型怎么理解","description":"厘清 DMA-BUF、DMA-BUF Heaps 与 CMA 的分层关系，并给出板端验证方法","frontmatter":{"title":"DMA-BUF Heaps 与 CMA：RK3588 连续内存模型怎么理解","description":"厘清 DMA-BUF、DMA-BUF Heaps 与 CMA 的分层关系，并给出板端验证方法","tags":["RK3588","DMA-BUF","CMA","Linux Kernel"],"date":"2026/07/13"},"headers":[],"relativePath":"linux/dmabuf-heaps-cma.md","filePath":"linux/dmabuf-heaps-cma.md","lastUpdated":1784519165000}'),p={name:"linux/dmabuf-heaps-cma.md"};function l(t,a,d,h,r,o){return i(),e("div",null,[...a[0]||(a[0]=[n(`<h1 id="dma-buf-heaps-与-cma-rk3588-连续内存模型怎么理解" tabindex="-1">DMA-BUF Heaps 与 CMA：RK3588 连续内存模型怎么理解 <a class="header-anchor" href="#dma-buf-heaps-与-cma-rk3588-连续内存模型怎么理解" aria-label="Permalink to &quot;DMA-BUF Heaps 与 CMA：RK3588 连续内存模型怎么理解&quot;">​</a></h1><p>在摄像头、RGA、NPU 和编码器之间共享图像时，经常会同时看到 DMA-BUF、DMA-BUF Heaps 与 CMA。它们不是三套并列的内存方案，而是位于不同层次。</p><h2 id="三个概念的关系" tabindex="-1">三个概念的关系 <a class="header-anchor" href="#三个概念的关系" aria-label="Permalink to &quot;三个概念的关系&quot;">​</a></h2><ul><li><strong>DMA-BUF</strong>：一个跨驱动、跨设备、跨进程共享 buffer 的通用句柄机制，用户态通常拿到一个 fd。</li><li><strong>DMA-BUF Heaps</strong>：用户态申请 DMA-BUF 的标准接口，设备节点通常位于 <code>/dev/dma_heap/</code>。</li><li><strong>CMA</strong>：内核用于获得较大块物理连续内存的后端机制之一。</li></ul><p>因此，更准确的描述是：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>应用通过 /dev/dma_heap/&lt;heap&gt; 申请</span></span>
<span class="line"><span>              ↓</span></span>
<span class="line"><span>DMA_HEAP_IOCTL_ALLOC 返回 dma-buf fd</span></span>
<span class="line"><span>              ↓</span></span>
<span class="line"><span>heap 选择自己的分配后端（其中可能使用 CMA）</span></span>
<span class="line"><span>              ↓</span></span>
<span class="line"><span>fd 被导入 V4L2 / RGA / OpenCL / MPP</span></span></code></pre></div><p><strong>DMA-BUF Heaps 是分配接口，CMA 是可能的内核后端。</strong> 把二者说成“先用 DMA-BUF，再用 CMA”会混淆调用层次。</p><h2 id="一个典型的申请与导入流程" tabindex="-1">一个典型的申请与导入流程 <a class="header-anchor" href="#一个典型的申请与导入流程" aria-label="Permalink to &quot;一个典型的申请与导入流程&quot;">​</a></h2><div class="language-cpp vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">cpp</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">int</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> heap_fd </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> open</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;/dev/dma_heap/system-uncached&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, O_RDWR </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">|</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> O_CLOEXEC);</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">dma_heap_allocation_data data{};</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">data.len </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> buffer_size;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">data.fd_flags </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> O_RDWR </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">|</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> O_CLOEXEC;</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">ioctl</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(heap_fd, DMA_HEAP_IOCTL_ALLOC, </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&amp;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">data);</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">int</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> dma_fd </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> data.fd;</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// 将 dma_fd 放进 v4l2_buffer 的 planes，再以 V4L2_MEMORY_DMABUF 入队</span></span></code></pre></div><p>后续 RGA、OpenCL 或 MPP 如果支持 dma-buf import，就可以继续使用同一个 fd 描述的内存，而不必先复制到普通堆内存。</p><h2 id="cmafree-0-kb-不一定等于-cma-耗尽" tabindex="-1"><code>CmaFree: 0 kB</code> 不一定等于 CMA 耗尽 <a class="header-anchor" href="#cmafree-0-kb-不一定等于-cma-耗尽" aria-label="Permalink to &quot;\`CmaFree: 0 kB\` 不一定等于 CMA 耗尽&quot;">​</a></h2><p>板端排查时，一个常见误判是看到 <code>/proc/meminfo</code> 里的 <code>CmaFree</code> 为 0，就直接得出“连续内存已耗尽”。这个结论必须结合内核配置。</p><p>某些系统启用了类似 <code>CONFIG_CMA_INACTIVE</code> 的策略，CMA 页在空闲时可能以不同方式进入普通内存管理，此时 <code>CmaFree</code> 或 <code>nr_free_cma</code> 不能单独代表可分配余量。</p><p>更有价值的证据包括：</p><ul><li>CMA 分配成功/失败计数；</li><li><code>/sys/kernel/debug/dma_buf/bufinfo</code> 中的 owner 与 size；</li><li>camera、NPU、ISP、编码器重启时是否出现 allocation failure；</li><li>峰值负载或双 buffer pool 重叠时是否失败；</li><li>普通 <code>MemAvailable</code> 是否被过大的保留区长期挤压。</li></ul><h2 id="如何估算生产容量" tabindex="-1">如何估算生产容量 <a class="header-anchor" href="#如何估算生产容量" aria-label="Permalink to &quot;如何估算生产容量&quot;">​</a></h2><p>先做 buffer 预算，而不是只看一张静态内存截图：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>总预算 = Σ(宽 × 高 × 每像素字节 × buffer 数)</span></span>
<span class="line"><span>       + stride/alignment</span></span>
<span class="line"><span>       + ISP/RGA/NPU/MPP 内部池</span></span>
<span class="line"><span>       + 重启或切换期间的短时重叠</span></span>
<span class="line"><span>       + 安全余量</span></span></code></pre></div><p>NV12 通常按约 <code>1.5 byte/pixel</code> 估算，但实际还要加 stride 和对齐。多相机系统还要考虑采集队列、矫正输出、算法输入和编码队列是否同时驻留。</p><p>容量选择的目标不是“越大越安全”。CMA 太小会在峰值或重启重叠时失败，太大则可能长期压缩普通 RAM。最终选择应来自真实负载下的 owner 分布、allocation failure 和重启测试。</p><h2 id="板端检查顺序" tabindex="-1">板端检查顺序 <a class="header-anchor" href="#板端检查顺序" aria-label="Permalink to &quot;板端检查顺序&quot;">​</a></h2><ol><li>确认使用的 <code>/dev/dma_heap/&lt;heap&gt;</code>；</li><li>确认 V4L2 是否使用 <code>V4L2_MEMORY_DMABUF</code>；</li><li>查看 DMA-BUF owner 和总量；</li><li>记录分配失败计数；</li><li>在完整负载下执行服务重启；</li><li>对照稳定态、峰值和重启重叠三个窗口判断余量。</li></ol><p>真正需要回答的不是“CmaFree 为什么是 0”，而是：<strong>当前主链在最差运行窗口里，是否还能可靠获得它需要的 buffer。</strong></p>`,23)])])}const E=s(p,[["render",l]]);export{k as __pageData,E as default};
